// R4 Gate B1/M1 targeted production Chromium. Fixtures generated by genuine Formal orders.
// node scripts/verify-r4-gate-delta-browser.mjs <external-playwright> <temporary-fixtures> <evidence-dir>
import fs from 'node:fs/promises';import path from 'node:path';import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';
const [pw,fixtures,out]=process.argv.slice(2);await fs.mkdir(out,{recursive:true});const {chromium}=await import(pathToFileURL(path.resolve(pw)).href);const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});const result={browser:browser.version(),viewport:{width:1440,height:900},source:'isolated R4 production build, reviewed baseline 608de8a plus B1/M1 delta',controlled:true,aiDecisionsDeferredDays:30,cases:[],manualPending:['original M3 Lv15 player manual acceptance','physical phone','hardware GPU FPS','six civilization full manual chain','deployed old SW upgrade','private late save','long-term calibration']},errors=[];
async function state(page){return page.evaluate(async()=>{const name=(await indexedDB.databases()).find(d=>d.name?.includes('formal'))?.name;if(!name)return null;const db=await new Promise((res,rej)=>{const r=indexedDB.open(name);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});const row=await new Promise((res,rej)=>{const r=db.transaction('saves').objectStore('saves').get('current');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});db.close();return row?.data?.snapshot??null;});}
for(const fixture of ['browser-B1.realm-save','browser-M1-false.realm-save','browser-M1-true.realm-save']){const label=fixture.replace('browser-','').replace('.realm-save',''),before=JSON.parse(await fs.readFile(path.join(fixtures,fixture),'utf8')).snapshot,context=await browser.newContext({viewport:result.viewport,locale:'zh-TW',timezoneId:'Asia/Taipei',serviceWorkers:'block'});await context.addInitScript(()=>{window.__events=[];const Native=Worker;window.Worker=class extends Native{constructor(...a){super(...a);this.addEventListener('message',e=>{if(['error','switchFailed','loaded','switched'].includes(e.data.type))window.__events.push(e.data);});}};});const page=await context.newPage();page.setDefaultTimeout(20000);page.on('pageerror',e=>errors.push({label,type:'pageerror',text:e.message}));page.on('console',m=>{if(m.type()==='error')errors.push({label,type:'console',text:m.text()});});page.on('response',r=>{if(r.status()>=400)errors.push({label,type:'http',url:r.url(),status:r.status()});});
try{await page.goto('http://127.0.0.1:4176/');await page.locator('input[type=file]').setInputFiles(path.join(fixtures,fixture));await page.getByRole('button',{name:'確認匯入',exact:true}).click();await page.locator('.formal-shell').waitFor();await page.screenshot({path:path.join(out,label+'-before.png'),fullPage:true});const eventAt=label==='B1'?before.combat.battles[0].nextRoundAt:before.armies.find(a=>a.ownerFactionId===before.factions[2].id).arrivalAt;let after;const end=Date.now()+20000;while(Date.now()<end){after=await state(page);if(after&&after.time>=eventAt+1000)break;await page.waitForTimeout(300);}assert.ok(after.time>=eventAt+1000,'world did not progress past boundary');assert.equal(await page.evaluate(()=>window.__events.some(e=>e.type==='error'||e.type==='switchFailed')),false);
if(label==='B1'){const dead=before.factions[1].id;assert.equal(after.cities.some(c=>c.ownerFactionId===dead),false);assert.equal(after.extinction.sites.filter(s=>s.sourceFactionId===dead).length,1);assert.equal(after.combat.battles.length,0);assert.equal(after.combat.receipts.filter(r=>r.battleId===before.combat.battles[0].id&&r.kind==='final').length,1);await page.locator('nav[aria-label="遊戲主要功能"] button').filter({hasText:'戰報紀事'}).click();await page.locator('.reports-list').waitFor();await page.locator('.compact-report summary').first().click();await page.screenshot({path:path.join(out,label+'-final-report.png'),fullPage:true});}
else{const craft=after.extinction.craftsmen[0];assert.equal(after.cities[0].ownerFactionId,after.factions[2].id);assert.equal(craft.ownerFactionId,after.playerFactionId);assert.equal(craft.cityId,null);assert.equal(craft.destinationCityId,after.cities[1].id);assert.ok(craft.arrivalAt>after.time);assert.equal(after.cities[0].buildings.castle,undefined);assert.equal(after.cities[0].economy.construction.some(j=>j.castleCivilizationId),false);await page.locator('nav[aria-label="遊戲主要功能"] button').filter({hasText:'天下勢力'}).click();await page.screenshot({path:path.join(out,label+'-evacuating.png'),fullPage:true});}
const nav=page.locator('nav[aria-label="遊戲主要功能"] button').filter({hasText:'戰役設定'});await nav.click();await page.getByRole('button',{name:'立即保存',exact:true}).click();await page.getByRole('button',{name:'重新讀取',exact:true}).click();await page.locator('.formal-shell').waitFor();await page.waitForTimeout(1500);const reload=await state(page);assert.ok(reload.time>=after.time);if(label==='B1'){assert.equal(reload.extinction.sites.filter(s=>s.sourceFactionId===before.factions[1].id).length,1);assert.equal(reload.cities.some(c=>c.ownerFactionId===before.factions[1].id),false);}else assert.equal(reload.extinction.craftsmen.length,1);await page.screenshot({path:path.join(out,label+'-reload.png'),fullPage:true});result.cases.push({name:label,status:'PASS',worldBefore:before.time,eventAt,worldAfter:after.time,worldAfterReload:reload.time,ownerAfter:after.cities[0].ownerFactionId,finals:after.combat.receipts.filter(r=>r.kind==='final').map(r=>({battleId:r.battleId,outcome:r.outcome})),craftsmen:after.extinction.craftsmen,exiles:after.extinction.sites.map(s=>({id:s.id,owner:s.sourceFactionId,units:s.defenders})),realIndexedDB:true,reload:true});}
catch(e){result.cases.push({name:label,status:'FAIL',error:String(e)});await page.screenshot({path:path.join(out,label+'-FAIL.png'),fullPage:true}).catch(()=>{});}finally{await context.close();}console.log(JSON.stringify(result.cases.at(-1)));}
await browser.close();result.errors=errors;result.passed=result.cases.filter(c=>c.status==='PASS').length;result.failed=result.cases.filter(c=>c.status==='FAIL').length;await fs.writeFile(path.join(out,'browser.json'),JSON.stringify(result,null,2));await fs.writeFile(path.join(out,'console.json'),JSON.stringify(errors,null,2));if(result.failed||errors.length)process.exitCode=1;
